function stopSweep(){playing=false;$('#sunPlay').textContent='▷ Play day'}$('#sunPlay').onclick=()=>{playing=!playing;$('#sunPlay').textContent=playing?'Ⅱ Pause day':'▷ Play day';if(playing){window.jaliStudy.set({mode:'site'});if(!active)$('#view3d').click();setCamera('shadows')}};
document.querySelectorAll('[data-sun]').forEach(b=>b.onclick=()=>{stopSweep();const p={morning:{elevation:25,azimuth:-50,strength:3.8},midday:{elevation:68,azimuth:0,strength:4},evening:{elevation:14,azimuth:35,strength:3.3},overcast:{...window.jaliStudy.get().manual,strength:0}};window.jaliStudy.set({mode:'manual',manual:p[b.dataset.sun]});if(!active)$('#view3d').click();setCamera('shadows')});
let priorSpace=JSON.stringify([window.jaliStudy.get().distance,window.jaliStudy.get().receiver]);window.addEventListener('jali-study',()=>{const value=window.jaliStudy.get(),next=JSON.stringify([value.distance,value.receiver]);if(next!==priorSpace){priorSpace=next;needsRebuild=true;if(active){rebuild();needsRebuild=false;setCamera(currentCamera)}}updateLight()});
$('#wallView').onclick=()=>setCamera('wall');$('#shadowView').onclick=()=>setCamera('shadows');$('#eyeView').onclick=()=>setCamera('eye');
$('#showContext').onchange=()=>{if(architecture)architecture.group.visible=$('#showContext').checked;dirty=true};$('#showScale').onchange=()=>{if(scaleFigure)scaleFigure.visible=$('#showScale').checked;if(scaleLabel)scaleLabel.visible=$('#showScale').checked;dirty=true};window.addEventListener('jali-units',updateLight);$('#showDimensions').onchange=()=>{if(annotations)annotations.visible=$('#showDimensions').checked;dirty=true};
window.addEventListener('jali-snapshot',()=>{if(!renderer){window.dispatchEvent(new CustomEvent('jali-unavailable'));return}if(!active)$('#view3d').click();updateAnnotationScale();renderer.render(scene,camera);renderer.domElement.toBlob(blob=>{if(!blob)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='jali-light-study.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})});
try{init();updateLight()}catch(e){delete window.jaliScene;console.error('3D initialization failed',e);$('#sceneLoading').hidden=true;window.dispatchEvent(new CustomEvent('jali-unavailable'))}
